#include "PhysicsWorld.h"
#include <cstdio>
#include <cmath>
#include <array>
unsigned checks=0,failures=0;
void check(bool b,const char* s){++checks;failures+=!b;printf("%s %s\n",b?"PASS":"FAIL",s);}
struct Result{glm::vec3 p,v,w;PhysicsWorld::StepStats stats;};
Result run(float spin,bool wall){PhysicsWorld w;w.Init();if(wall)w.CreateStaticBox({0,0,0},{.015f,3,3},0,0);else w.CreateStaticBox({0,-.1f,0},{5,.1f,5},0,0);auto b=w.CreateDynamicSphere(wall?glm::vec3(-2,0,0):glm::vec3(0,.22f,0),.2f,1,0,0);w.SetLinearVelocity(b,wall?glm::vec3(180,0,0):glm::vec3(50,0,0));w.SetAngularVelocity(b,{0,0,spin});w.Step(1.f/60);return {w.GetTransform(b).position,w.GetLinearVelocity(b),w.GetAngularVelocity(b),w.LastStepStats()};}
void planeSpin(bool rotated){PhysicsWorld w;w.Init();const auto q=rotated?glm::angleAxis(1.1f,glm::normalize(glm::vec3(1,2,3))):glm::quat(1,0,0,0);w.CreateStaticBox(q*glm::vec3(0,-.1f,0),q,{5,.1f,5},0,0);auto b=w.CreateShape(Shape::Box({.3f,.02f,.3f}),{q*glm::vec3(0,.02f,0),q},true,1,0,0);w.SetAngularVelocity(b,q*glm::vec3(0,1000,0));w.Step(1.f/60);auto s=w.LastStepStats();printf("PLANE SPIN rotated=%d queries=%zu advances=%zu samples=%zu ms=%.6f\n",int(rotated),s.impactQueries,s.impactSearchIterations,s.impactSamplingTests,s.totalMilliseconds);check(s.impactSamplingTests==0,"spin about actual support normal requires no penetration sampling");check(glm::length(w.GetAngularVelocity(b)-q*glm::vec3(0,1000,0))<.5f,"normal-axis physical spin retained");check((glm::inverse(q)*w.GetTransform(b).position).y>=.019f,"flat spinning body stays on actual rotated support");}
void tumble(){PhysicsWorld w;w.Init();w.CreateStaticBox({0,-.1f,0},{5,.1f,5},0,0);auto b=w.CreateDynamicBox({0,.22f,0},{.3f,.02f,.3f},1,0,0);w.SetAngularVelocity(b,{80,0,0});w.Step(1.f/60);auto stats=w.LastStepStats();check(stats.impactEvents>0,"real tumbling through support still produces continuous impacts");check(std::isfinite(w.GetTransform(b).position.y),"tumbling response remains finite");}
int main(){planeSpin(false);planeSpin(true);tumble();for(bool hit:{false,true}){auto a=run(0,hit),b=run(10000,hit);printf("CASE hit=%d no-spin queries=%zu advances=%zu samples=%zu; spin queries=%zu advances=%zu samples=%zu ms=%.6f\n",int(hit),a.stats.impactQueries,a.stats.impactSearchIterations,a.stats.impactSamplingTests,b.stats.impactQueries,b.stats.impactSearchIterations,b.stats.impactSamplingTests,b.stats.totalMilliseconds);check(glm::length(a.p-b.p)<1e-4f&&glm::length(a.v-b.v)<1e-4f,"centred sphere spin does not change frictionless translation");check(std::abs(b.w.z-10000)<.1f,"physical spin remains present");if(hit)check(b.p.x<-.19f&&std::abs(b.v.x)<.01f&&b.stats.impactEvents>0,"thin wall CCD still catches fast spinning sphere");else check(b.p.x>.8f,"parallel sphere movement remains unimpeded");check(b.stats.impactSearchIterations<=a.stats.impactSearchIterations&&b.stats.impactSamplingTests<=a.stats.impactSamplingTests,"geometry-invariant spin adds no conservative search work");}printf("SUMMARY checks=%u failures=%u\n",checks,failures);return failures?1:0;}
